import { expect, test } from '@playwright/test';

// Checks the page contract the harness will rely on (see app/views/pages.ts):
// elements are found only through data-* attributes. Per-workflow tests are
// generated by the harness from Milestone 3; these stay as a contract check.

test('health check answers and reports the AI seed in use', async ({ request }) => {
  const response = await request.get('/healthz');
  expect(await response.json()).toEqual({ ok: true, aiSeed: expect.any(String) as unknown });
});

test('lists published workflows with their steps', async ({ request }) => {
  const response = await request.get('/api/workflows');
  expect(response.ok()).toBe(true);
  const workflows = (await response.json()) as {
    id: string;
    published: boolean;
    steps: unknown[];
  }[];
  expect(workflows.map((workflow) => workflow.id)).toEqual([
    'customer-lookup',
    'invoice-extraction',
    'invoice-total',
    'order-categories',
    'order-confirmation',
    'order-total',
    'ticket-triage',
  ]);
  for (const workflow of workflows) {
    expect(workflow.published).toBe(true);
    expect(workflow.steps.length).toBeGreaterThan(0);
  }
});

test('mock API gives identical responses to identical requests', async ({ request }) => {
  const bodies = await Promise.all(
    [1, 2, 3].map(async () => (await request.get('/api/customers/C-1002')).text()),
  );
  expect(new Set(bodies).size).toBe(1);
});

test('pages expose workflow, step and fields through data attributes', async ({ page }) => {
  await page.goto('/run/order-total');
  const main = page.locator('main[data-workflow-id="order-total"]');
  await expect(main).toHaveAttribute('data-step-id', 'order');
  await expect(main).toHaveAttribute('data-block', 'form');
  await expect(main).toHaveAttribute('data-run-status', 'in-progress');

  await page.locator('[data-field="quantity"]').fill('3');
  await page.locator('[data-field="unitPrice"]').fill('19.99');
  await page.locator('[data-action="submit"]').click();

  await expect(main).toHaveAttribute('data-step-id', 'receipt');
  await expect(page.locator('[data-field="total"]')).toHaveText('64.92');

  await page.locator('[data-action="continue"]').click();
  await expect(main).toHaveAttribute('data-run-status', 'complete');
  await expect(main).not.toHaveAttribute('data-step-id');
});

test('invalid input re-renders the form with field errors', async ({ page }) => {
  await page.goto('/run/order-total');
  await page.locator('[data-field="quantity"]').fill('three');
  await page.locator('[data-action="submit"]').click();
  await expect(page.locator('[data-field-error="quantity"]')).toBeVisible();
  await expect(page.locator('[data-field-error="unitPrice"]')).toBeVisible();
  await expect(page.locator('main')).toHaveAttribute('data-step-id', 'order');
});

test('table rows and cells carry their state paths', async ({ page }) => {
  await page.goto('/run/customer-lookup');
  await page.locator('[data-field="customerId"]').fill('C-1002');
  await page.locator('[data-action="submit"]').click();
  await expect(page.locator('[data-field="fullName"]')).toHaveText('Tomas Lindqvist');
  await page.locator('[data-action="continue"]').click();

  await expect(page.locator('main')).toHaveAttribute('data-block', 'table');
  await expect(page.locator('[data-row-index]')).toHaveCount(2);
  await expect(page.locator('[data-field="customer.orders.1.item"]')).toHaveText('USB-C cable');
});
